using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Management;
using System.Security.Cryptography;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
class InfPlan {public string Path,Hash,Catalog,Class;public DriverRecord Target;}
static class VendorDrivers {
 public static string Board="Chưa đọc model bo mạch";
 public static List<DriverRecord> Scan(){var records=Drivers.Inventory();string manufacturer="",model="";using(var query=new ManagementObjectSearcher("SELECT Manufacturer,Product FROM Win32_BaseBoard")){query.Options.Timeout=TimeSpan.FromSeconds(30);using(var rows=query.Get())foreach(ManagementObject row in rows)using(row){manufacturer=Convert.ToString(row["Manufacturer"]);model=Convert.ToString(row["Product"]);break;}}Board=manufacturer+" · "+model;
  var indexed=records.Where(x=>!String.IsNullOrEmpty(x.Id)).GroupBy(x=>x.Id,StringComparer.OrdinalIgnoreCase).ToDictionary(x=>x.Key,x=>x.First(),StringComparer.OrdinalIgnoreCase);
  using(var query=new ManagementObjectSearcher("SELECT DeviceID,Name,PNPClass,Manufacturer,HardwareID,ConfigManagerErrorCode FROM Win32_PnPEntity")){query.Options.Timeout=TimeSpan.FromSeconds(30);using(var rows=query.Get())foreach(ManagementObject row in rows)using(row){string id=Convert.ToString(row["DeviceID"]);if(String.IsNullOrEmpty(id))continue;DriverRecord record;if(!indexed.TryGetValue(id,out record)){record=new DriverRecord{Id=id,Device=Convert.ToString(row["Name"]),Class=Convert.ToString(row["PNPClass"]),Vendor=Convert.ToString(row["Manufacturer"]),Version="Chưa có bản ghi driver",Inf=""};records.Add(record);indexed[id]=record;}record.HardwareIds=row["HardwareID"] as string[];int code=Convert.ToInt32(row["ConfigManagerErrorCode"]);record.Status=code==0?"Thiết bị không báo lỗi":code==28?"Thiếu driver · mã 28":"Thiết bị báo mã "+code;}}
  foreach(var record in records){if(String.IsNullOrEmpty(record.Status))record.Status="Chưa có trạng thái thiết bị";Resolve(record,manufacturer,model);}return records.OrderBy(x=>x.Status.Contains("mã")?0:1).ThenBy(x=>x.Class=="DISPLAY"?0:x.Class=="MEDIA"?1:x.Class=="NET"?2:3).ThenBy(x=>x.Device).ToList();
 }
 public static void Resolve(DriverRecord record,string boardVendor,string boardModel){string vendor=(record.Vendor??"").ToLowerInvariant(),name=(record.Device??"").ToLowerInvariant();record.Url="";record.Source="Chưa xác minh nguồn riêng";
  if(vendor.Contains("nvidia")||name.StartsWith("nvidia")){record.Url="https://www.nvidia.com/en-us/software/nvidia-app/";record.Source="NVIDIA App / driver NVIDIA";}
  else if((boardVendor??"").ToLowerInvariant().Contains("asus")&&(vendor.Contains("realtek")||vendor.Contains("intel"))){
   if(String.Equals(boardModel,"PRIME H510M-K",StringComparison.OrdinalIgnoreCase)){record.Url="https://www.asus.com/motherboards-components/motherboards/prime/prime-h510m-k/helpdesk_download?model2Name=PRIME-H510M-K";record.Source="ASUS PRIME H510M-K · chọn đúng hệ điều hành";}
   else{record.Url="https://www.asus.com/support/download-center/";record.Source="ASUS Download Center · "+boardModel;}
  }
  else if((boardVendor??"").ToLowerInvariant().Contains("gigabyte")&&(vendor.Contains("realtek")||vendor.Contains("intel"))){record.Url="https://www.gigabyte.com/Support/Consumer/Download";record.Source="GIGABYTE Support · "+boardModel;}
  else if(((boardVendor??"").ToLowerInvariant().Contains("msi")||(boardVendor??"").ToLowerInvariant().Contains("micro-star"))&&(vendor.Contains("realtek")||vendor.Contains("intel"))){record.Url="https://www.msi.com/support/download";record.Source="MSI Download Center · "+boardModel;}
  else if((boardVendor??"").ToLowerInvariant().Contains("asrock")&&(vendor.Contains("realtek")||vendor.Contains("intel"))){record.Url="https://www.asrock.com/support/index.asp";record.Source="ASRock Support · "+boardModel;}
  else if((boardVendor??"").ToLowerInvariant().Contains("dell")&&(vendor.Contains("realtek")||vendor.Contains("intel"))){record.Url="https://www.dell.com/support/home";record.Source="Dell Support · "+boardModel;}
  else if((boardVendor??"").ToLowerInvariant().Contains("lenovo")&&(vendor.Contains("realtek")||vendor.Contains("intel"))){record.Url="https://pcsupport.lenovo.com/";record.Source="Lenovo Support · "+boardModel;}
  else if(((boardVendor??"").ToLowerInvariant().Contains("hp")||(boardVendor??"").ToLowerInvariant().Contains("hewlett"))&&(vendor.Contains("realtek")||vendor.Contains("intel"))){record.Url="https://support.hp.com/";record.Source="HP Support · "+boardModel;}
  else if(vendor.Contains("intel")){record.Url="https://www.intel.com/content/www/us/en/support/detect.html";record.Source="Intel Driver & Support Assistant";}
  else if(vendor.Contains("advanced micro devices")||vendor=="amd"){record.Url="https://www.amd.com/en/support/download/drivers.html";record.Source="AMD · driver và công cụ nhận diện";}
  else if(vendor.Contains("microsoft")){record.Source="Driver hệ thống đang có · không tìm/cài qua mạng";}
 }
 public static string Digest(string path){using(var file=File.OpenRead(path))using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(file)).Replace("-","");}
 public static bool SupportsId(string inf,string[] ids){if(ids==null)return false;var values=inf.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Split(';')[0]).Where(x=>x.Contains("=")).SelectMany(x=>x.Substring(x.IndexOf('=')+1).Split(',').Skip(1)).Select(x=>x.Trim().Trim('"')).ToArray();return ids.Any(id=>values.Contains(id,StringComparer.OrdinalIgnoreCase));}
 public static InfPlan Inspect(string path,DriverRecord device){path=System.IO.Path.GetFullPath(path);if(!Engine.LocalFile(path)||!Features.NoLinks(path)||!path.EndsWith(".inf",StringComparison.OrdinalIgnoreCase)||!File.Exists(path)||new FileInfo(path).Length>16*1024*1024)throw new Exception("Chọn tệp INF cục bộ đã giải nén từ gói của hãng.");string content=File.ReadAllText(path);var cls=Regex.Match(content,@"(?im)^\s*Class\s*=\s*([^;\r\n]+)");string type=cls.Groups[1].Value.Trim().Trim('"');if(!new[]{"Display","Media","Net","Bluetooth","HIDClass","USB","Printer","Image"}.Contains(type,StringComparer.OrdinalIgnoreCase)||!String.Equals(type,device.Class,StringComparison.OrdinalIgnoreCase))throw new Exception("Gói INF không cùng nhóm thiết bị được hỗ trợ. Dùng bộ cài chính thức của hãng cho chipset/thành phần khác.");if(!SupportsId(content,device.HardwareIds))throw new Exception("Không thấy mã phần cứng của thiết bị trong INF. Không cài gói này.");var cat=Regex.Matches(content,@"(?im)^\s*CatalogFile(?:\.NTAMD64)?\s*=\s*([^;\r\n]+)").Cast<Match>().LastOrDefault();if(cat==null)throw new Exception("Không tìm thấy CatalogFile để xác minh gói.");string name=cat.Groups[1].Value.Trim().Trim('"');if(System.IO.Path.GetFileName(name)!=name)throw new Exception("Đường dẫn catalog không hợp lệ.");string catalog=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(path),name);bool trusted;SignatureCheck.Check(catalog,out trusted);if(!trusted)throw new Exception("Chưa xác minh được chữ ký catalog. Dừng cài.");return new InfPlan{Path=path,Hash=Digest(path),Catalog=catalog,Class=type,Target=device};}
 static Tuple<int,string> Run(string arguments){using(var proc=Process.Start(new ProcessStartInfo(System.IO.Path.Combine(Environment.SystemDirectory,"pnputil.exe"),arguments){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){var output=proc.StandardOutput.ReadToEndAsync();var error=proc.StandardError.ReadToEndAsync();proc.WaitForExit();Task.WaitAll(output,error);return Tuple.Create(proc.ExitCode,output.Result+"\n"+error.Result);}}
 public static string Install(InfPlan plan,IProgress<string> progress){if(!Drivers.Administrator())throw new Exception("Cài gói driver cần quyền Administrator.");var live=Scan().FirstOrDefault(x=>String.Equals(x.Id,plan.Target.Id,StringComparison.OrdinalIgnoreCase));if(live==null)throw new Exception("Thiết bị không còn tồn tại.");var current=Inspect(plan.Path,live);if(current.Hash!=plan.Hash)throw new Exception("Gói đã đổi sau khi xem trước.");string folder=System.IO.Path.Combine(Engine.Data,"Driver-backups",DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);progress.Report("Đang sao lưu các gói driver bên thứ ba trước khi cài…");var backup=Run("/export-driver * "+Maintenance.Quote(folder));File.WriteAllText(System.IO.Path.Combine(folder,"backup.log"),backup.Item2);if(backup.Item1!=0||Directory.GetFiles(folder,"*.inf",SearchOption.AllDirectories).Length==0)throw new Exception("Không xác nhận được bản sao driver; đã dừng trước khi cài. "+backup.Item2);if(Digest(plan.Path)!=plan.Hash)throw new Exception("INF đã thay đổi trong lúc sao lưu; dừng cài.");progress.Report("Đang cài gói driver cục bộ. Có thể gián đoạn màn hình/mạng; không tắt máy.");var installed=Run("/add-driver "+Maintenance.Quote(plan.Path)+" /install");string report="PnPUtil exit="+installed.Item1+"\n"+installed.Item2+"\nBản sao driver: "+folder+"\nPnPUtil chọn driver phù hợp theo xếp hạng; mã thành công không đảm bảo đã thay phiên bản. Quét lại để đối chiếu. Không tự khởi động lại.";File.WriteAllText(System.IO.Path.Combine(folder,"install.log"),report);Engine.Log("LOCAL_DRIVER_INSTALL "+plan.Path+" | exit="+installed.Item1);return report;}
}
